function nowYm() {
  const p = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit' }).format(new Date()).split('-');
  return { y: parseInt(p[0], 10), m: parseInt(p[1], 10), mk: p[0] + '-' + p[1] };
}

