function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }

function summarize(r) {
  if (r === null || r === undefined) return '(값 없음)';
  if (typeof r === 'string') return '글 ' + r.length + '자 (' + r.slice(0, 40) + ')';
  if (Array.isArray(r)) return '목록 ' + r.length + '줄';
  if (typeof r !== 'object') return String(r);
  const bits = [];
  if ('success' in r) bits.push('success=' + r.success);
  if (r.message) bits.push('message=' + String(r.message).slice(0, 160));
  for (const k of ['rows', 'data', 'files', 'list', 'logs', 'sheets', 'snapshots', 'months', 'items']) {
    if (Array.isArray(r[k])) bits.push(k + ' ' + r[k].length + '줄');
  }
  if (r.cached) bits.push('cached');
  return bits.join(' · ') || ('항목 ' + Object.keys(r).length + '개');
}

async function runChecks(userId, baseUrl) {
  const out = [];
  for (const [group, fn, args, project] of checkList()) {
    const t0 = Date.now();
    let ok = false, note = '';
    try {
      const r = await host.run(fn.trim(), args, { userId, baseUrl, project: project || 'main' });
      ok = !(r && typeof r === 'object' && (r.success === false || r.ok === false || (r.error && !r.success)));
      note = summarize(r);
    } catch (e) {
      note = '오류: ' + e.message + (e.gasStack ? '\n' + e.gasStack.split('\n').slice(0, 4).join('\n') : '');
    }
    out.push({ group, fn, args: JSON.stringify(args), ok, ms: Date.now() - t0, note });
  }
  // 보정 규칙(patches/*.rules.json) 가운데 원본에서 자리를 찾지 못해 적용하지 못한 것
  const rl = (typeof host.ruleLog === 'function') ? host.ruleLog() : [];
  out.push({ group: '보정 규칙', fn: '바꿈 규칙 적용', args: '[]', ok: rl.length === 0, ms: 0, note: rl.length ? rl.join('\n') : '모두 적용됨' });
  return out;
}

